<script setup>
import {computed,ref,onBeforeUnmount} from 'vue'
import {useI18n} from 'vue-i18n'
import {getStartupProfile,updateStartupProfile} from '@/api/startup'
import * as api from '@/api/network'
import Avatar from '@/components/ui/Avatar.vue'
import InlineLoader from '@/components/ui/InlineLoader.vue'
import ReportDialog from '@/components/network/ReportDialog.vue'
const {t}=useI18n()
const tab=ref('founders'),query=ref(''),profile=ref(null),founders=ref([]),connections=ref([]),posts=ref([])
const error=ref(''),loading=ref(true),busy=ref(false),editing=ref(false),draft=ref({}),composing=ref(false),post=ref({title:'',text:''}),image=ref(null)
const chat=ref(null),messages=ref([]),message=ref(''),matches=ref([]),notice=ref('')
let generation=0
const reporting=ref(null) // { type: 'post' | 'user' | 'message', id } while the report dialog is open
async function reload(){const id=++generation;loading.value=true;error.value='';try{const [p,n,f]=await Promise.all([getStartupProfile(),api.getNetwork(query.value),api.getPosts()]);if(id!==generation)return;profile.value=p;founders.value=n.founders;connections.value=n.connections;posts.value=f.posts}catch(e){if(id===generation)error.value=e?.response?.data?.detail||e.message}finally{if(id===generation)loading.value=false}}
reload()
const connection=id=>connections.value.find(c=>c.peer===id)
const sorted=computed(()=>[...founders.value].sort((a,b)=>(matches.value.some(m=>m.id===b.id)?1:0)-(matches.value.some(m=>m.id===a.id)?1:0)))
const reason=id=>matches.value.find(m=>m.id===id)?.reason
async function action(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e?.response?.data?.detail||e.message}finally{busy.value=false}}
function editProfile(){draft.value={name:profile.value.name,industry:profile.value.industry,public_summary:profile.value.public_summary,public_visible:profile.value.public_visible};editing.value=!editing.value}
async function saveProfile(){await action(async()=>{profile.value=await updateStartupProfile(draft.value);editing.value=false;await reload()})}
async function connect(p){await action(async()=>{await api.connectFounder(p.id);await reload()})}
async function accept(c){await action(async()=>{await api.acceptConnection(c.id);await reload()})}
async function disconnect(c){await action(async()=>{await api.removeConnection(c.id);if(chat.value?.id===c.id)chat.value=null;await reload()})}
let chatGeneration=0
async function openChat(p){const c=connection(p.id);const id=++chatGeneration;chat.value={...c,name:p.founder};messages.value=[];await action(async()=>{const result=await api.getMessages(c.id);if(id===chatGeneration)messages.value=result.messages})}
async function refreshChat(){const c=chat.value;const id=chatGeneration;if(!c)return;await action(async()=>{const result=await api.getMessages(c.id);if(id===chatGeneration)messages.value=result.messages})}
async function send(){const c=chat.value;const body=message.value.trim();if(!c||!body)return;await action(async()=>{const result=await api.sendMessage(c.id,body);if(chat.value?.id===c.id){messages.value=result.messages;message.value=''}})}
async function publish(){await action(async()=>{const p=await api.createPost(post.value);if(image.value){try{await api.uploadPostImage(p.id,image.value)}catch(e){await api.deletePost(p.id);throw e}}post.value={title:'',text:''};image.value=null;composing.value=false;await reload()})}
async function recommend(){await action(async()=>{const result=await api.recommendFounders();matches.value=result.matches;notice.value=result.is_stub?t('business.aiUnavailable'):result.matches.length?'':t('network.noMatches')})}
onBeforeUnmount(()=>{generation++;chatGeneration++})
</script>
<template>
  <div class="mx-auto max-w-6xl">
    <header class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-widest text-brand-600">ZINVEST NETWORK</p><h1 class="mt-2 text-3xl font-extrabold">{{ $t('network.title') }}</h1><p class="mt-3 max-w-xl text-slate-500">{{ $t('network.intro') }}</p></div><button v-if="profile" class="min-h-11 rounded-xl border border-hairline px-4 font-semibold" @click="editProfile">{{ $t('network.profile') }}</button></header>
    <p v-if="error" role="alert" class="mt-5 rounded-xl bg-red-50 p-4 text-red-700">{{ error }}</p>
    <form v-if="editing" class="card mt-6 space-y-4 p-5" @submit.prevent="saveProfile"><div class="grid gap-4 sm:grid-cols-2"><label>{{ $t('network.company') }}<input v-model="draft.name" required maxlength="120" class="zx-input mt-1 w-full" /></label><label>{{ $t('network.industry') }}<input v-model="draft.industry" maxlength="80" class="zx-input mt-1 w-full" /></label></div><label class="block">{{ $t('network.summary') }}<textarea v-model="draft.public_summary" rows="3" maxlength="3000" class="zx-input mt-1 w-full" /></label><label class="flex gap-3"><input v-model="draft.public_visible" type="checkbox" />{{ $t('network.visible') }}</label><p class="text-xs text-slate-500">{{ $t('network.privacy') }}</p><button :disabled="busy" class="min-h-11 rounded-xl bg-brand-600 px-5 text-white">{{ $t('common.save') }}</button></form>
    <div class="mt-7 flex flex-wrap gap-2 border-b border-hairline pb-3"><button v-for="value in ['founders','feed']" :key="value" class="min-h-11 rounded-xl px-5 font-semibold" :class="tab===value?'bg-brand-600 text-white':'text-slate-500'" :aria-pressed="tab===value" @click="tab=value">{{ $t(`network.${value}`) }}</button></div>
    <InlineLoader v-if="loading" class="py-12" />
    <template v-else-if="tab==='founders'">
      <div class="my-5 flex flex-wrap gap-3"><form class="flex min-w-0 flex-1 gap-2" @submit.prevent="reload"><input v-model="query" class="zx-input min-w-0 flex-1" :aria-label="$t('network.search')" :placeholder="$t('network.search')" /><button class="min-h-11 rounded-xl border border-hairline px-4">{{ $t('network.searchButton') }}</button></form><button :disabled="busy" class="min-h-11 rounded-xl bg-brand-50 px-5 font-semibold text-brand-700 dark:bg-brand-500/15 dark:text-brand-300" @click="recommend">{{ $t('network.recommend') }}</button></div>
      <p v-if="notice" role="status" class="mb-4 text-sm text-slate-500">{{ notice }}</p>
      <div v-if="!sorted.length" class="card py-16 text-center"><h2 class="text-xl font-bold">{{ $t('network.empty') }}</h2><p class="mt-2 text-slate-500">{{ $t('network.emptyHint') }}</p></div>
      <div class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="p in sorted" :key="p.id" class="card flex flex-col p-5"><div class="flex gap-3"><Avatar :name="p.founder" :src="p.photo_url||''" size="h-12 w-12" /><div><h2 class="font-bold">{{ p.founder }}</h2><p class="text-sm text-brand-600">{{ p.name }}</p></div></div><p class="mt-4 text-xs font-semibold text-slate-500">{{ p.industry }} · {{ p.team_size }} {{ $t('network.people') }}</p><p class="mt-3 whitespace-pre-wrap break-words text-sm leading-relaxed text-slate-600 dark:text-slate-300">{{ p.summary }}</p><p v-if="reason(p.id)" class="mt-4 rounded-xl bg-brand-50 p-3 text-sm dark:bg-brand-500/10">{{ reason(p.id) }}</p>
      <div class="mt-auto flex flex-wrap gap-2 pt-5"><button v-if="!connection(p.id)" :disabled="busy" class="min-h-11 rounded-xl bg-brand-600 px-4 text-sm font-semibold text-white" @click="connect(p)">{{ $t('network.connect') }}</button><template v-else-if="connection(p.id).accepted"><button :disabled="busy" class="min-h-11 rounded-xl bg-brand-600 px-4 text-sm text-white" @click="openChat(p)">{{ $t('network.message') }}</button><button :disabled="busy" class="min-h-11 px-2 text-xs text-slate-500" @click="disconnect(connection(p.id))">{{ $t('network.disconnect') }}</button></template><template v-else><button v-if="connection(p.id).incoming" :disabled="busy" class="min-h-11 rounded-xl bg-brand-600 px-4 text-sm text-white" @click="accept(connection(p.id))">{{ $t('network.accept') }}</button><span v-else class="flex min-h-11 items-center text-sm text-slate-500">{{ $t('network.pending') }}</span><button :disabled="busy" class="min-h-11 px-3 text-sm text-slate-500" @click="disconnect(connection(p.id))">{{ $t('common.cancel') }}</button></template><button class="ml-auto min-h-11 px-2 text-xs text-slate-400 hover:text-red-600" @click="reporting={type:'user',id:p.id}">{{ $t('admin.report.action') }}</button></div></article></div>
    </template>
    <template v-else><div class="my-5 flex items-center justify-between gap-3"><p class="text-sm text-slate-500">{{ $t('network.feedHint') }}</p><button class="min-h-11 shrink-0 rounded-xl bg-brand-600 px-4 font-semibold text-white" @click="composing=!composing">{{ $t('network.newPost') }}</button></div>
    <form v-if="composing" class="card mb-5 space-y-4 p-5" @submit.prevent="publish"><label class="block">{{ $t('network.postTitle') }}<input v-model="post.title" required maxlength="120" class="zx-input mt-1 w-full" /></label><label class="block">{{ $t('network.postText') }}<textarea v-model="post.text" rows="3" maxlength="5000" class="zx-input mt-1 w-full" /></label><label class="block text-sm">{{ $t('network.image') }}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" class="mt-2 block max-w-full" @change="image=$event.target.files?.[0]" /></label><button :disabled="busy" class="min-h-11 rounded-xl bg-brand-600 px-5 text-white">{{ $t('network.publish') }}</button></form>
    <p v-if="!posts.length" class="card py-16 text-center text-slate-500">{{ $t('network.emptyFeed') }}</p><div class="columns-1 gap-5 md:columns-2 xl:columns-3"><article v-for="p in posts" :key="p.id" class="card mb-5 break-inside-avoid overflow-hidden"><img v-if="p.image_url" :src="p.image_url" :alt="p.title" loading="lazy" class="w-full object-cover" /><div class="p-5"><p class="text-xs font-semibold text-brand-600">{{ p.founder.name }}</p><h2 class="mt-2 text-xl font-bold">{{ p.title }}</h2><p class="mt-3 whitespace-pre-wrap break-words text-sm leading-relaxed text-slate-500">{{ p.text }}</p><p class="mt-5 text-xs text-slate-500">{{ p.founder.founder }} · {{ new Date(p.created_at).toLocaleDateString() }}</p><button v-if="p.mine" :disabled="busy" class="mt-2 min-h-11 text-sm text-red-600" @click="action(async()=>{await api.deletePost(p.id);await reload()})">{{ $t('common.delete') }}</button><button v-else class="mt-2 min-h-11 text-xs text-slate-400 hover:text-red-600" @click="reporting={type:'post',id:p.id}">{{ $t('admin.report.action') }}</button><p v-if="p.mine&&p.hidden" class="mt-2 rounded-xl bg-amber-50 p-3 text-xs text-amber-800 dark:bg-amber-500/10 dark:text-amber-200">{{ $t('admin.report.hiddenPost') }}</p></div></article></div></template>
    <section v-if="chat" class="fixed inset-x-3 bottom-3 z-50 flex max-h-[75vh] flex-col rounded-2xl border border-hairline bg-white p-5 shadow-2xl dark:bg-surface sm:left-auto sm:w-96" :aria-label="$t('network.message')"><header class="flex items-center justify-between gap-2"><h2 class="font-bold">{{ chat.name }}</h2><button class="min-h-11 px-2 text-xs text-brand-600" :disabled="busy" @click="refreshChat">{{ $t('network.refresh') }}</button><button class="min-h-11 px-2" :aria-label="$t('common.close')" @click="chat=null;chatGeneration++">×</button></header><div class="my-3 min-h-24 space-y-3 overflow-y-auto" role="log" aria-live="polite"><div v-for="m in messages" :key="m.id" :class="m.mine?'ml-7':'mr-7'"><p class="whitespace-pre-wrap break-words rounded-xl p-3 text-sm" :class="m.mine?'bg-brand-600 text-white':'bg-slate-100 dark:bg-surface-2'">{{ m.text }}</p><button v-if="!m.mine" class="px-1 text-[11px] text-slate-400 hover:text-red-600" @click="reporting={type:'message',id:m.id}">{{ $t('admin.report.action') }}</button></div></div><form class="flex gap-2" @submit.prevent="send"><input v-model="message" maxlength="5000" :aria-label="$t('network.message')" class="zx-input min-w-0 flex-1" /><button :disabled="busy||!message.trim()" class="min-h-11 rounded-xl bg-brand-600 px-3 text-white disabled:opacity-50">{{ $t('bear.ask') }}</button></form></section>
    <ReportDialog :target="reporting" @close="reporting=null" />
  </div>
</template>
